#!/usr/bin/env python3
"""Build 15 initial pass over every source area (spec v1.1 S19-03, P1-01..03).

Every non-test source file is mapped to an area and scanned for patterns that point at a known class
of defect. Each pattern category was reviewed by hand (the hits read in their context); REVIEWED
below is that verdict, applied to every area where the category occurs. The table records, per
area, the files, the hits per category and the resulting findings, or "reviewed, none".

  initial-pass.py            print the table
  initial-pass.py --write    write docs/plus/build15/initial-pass.md
  initial-pass.py --check    exit 1 if that file is out of date (run by the script tests)
"""
import collections
import re
import subprocess
import sys
from pathlib import Path

OUT = "docs/plus/build15/initial-pass.md"
ROOTS = ["composeApp/src", "androidApp/src", "baselineprofile", "iosApp"]
SOURCE = re.compile(r"\.(kt|kts|java|xml|swift|m|plist|pbxproj|xcconfig)$")
TEST = re.compile(r"(^|/)(\w*[Tt]est\w*)/")

# Category -> (pattern, verdict after reading every hit, finding ids it maps to).
CATEGORIES = {
    "process-exec": (r"Runtime\.getRuntime\(\)\.exec|ProcessBuilder\(", "none found", []),
    "webview-js": (r"addJavascriptInterface|setJavaScriptEnabled\(true\)", "none found", []),
    "tls-trust": (r"X509TrustManager|HostnameVerifier|trustAllCerts",
                  "player only: any certificate for streams without credentials (Nuvio's choice, kept); "
                  "credentials only over a verified certificate (#44)", ["B15-SEC-04"]),
    "cleartext-url": (r'"http://(?!localhost|127\.0\.0\.1|10\.0\.2\.2)',
                      "XML namespaces, scheme checks and public torrent trackers; no secret sent in clear by Plus", []),
    "secret-in-log": (r"(?i)(Log\.[dviwe]|log\.[dviwe]|println)\b[^\n]*(token|password|secret|api_?key|cookie|authorization)",
                      "messages only (e.g. 'token refresh failed'), no secret value logged", []),
    "raw-sql": (r"rawQuery\(|execSQL\(", "none found", []),
    "world-readable": (r"MODE_WORLD_(READ|WRIT)ABLE", "none found", []),
    "global-scope": (r"GlobalScope\.", "none found", []),
    "run-blocking": (r"runBlocking\s*[({]",
                     "string lookups (getString) and one header read off the main thread; brief, Nuvio's pattern",
                     ["B15-NUV-02"]),
    "catch-throwable": (r"catch\s*\(\s*\w+\s*:\s*Throwable\s*\)",
                        "also catches coroutine cancellation without rethrowing it", ["B15-NUV-01"]),
    "mutable-pending-intent": (r"FLAG_MUTABLE", "none found", []),
    "exported-component": (r'exported="true"', "launcher, deep links and the update receiver; reviewed in B15-AND-01",
                           ["B15-AND-01"]),
}
# Areas outside the Android build, with the reason.
EXCLUDED = {"iOS app": "iOS app: not part of the Android Build 15 (no iOS build is made or published)"}


def area_of(path):
    match = re.search(r"com/nuvio/app/(features|core)/([^/]+)/", path)
    if match:
        return f"{match.group(1)}/{match.group(2)}"
    if path.startswith("iosApp/") or "/iosMain/" in path or "/iosFull/" in path or "/iosAppStore/" in path \
            or "/nativeInterop/" in path:
        return "iOS app"
    if path.startswith("androidApp/"):
        return "androidApp module"
    if path.startswith("baselineprofile/"):
        return "baseline profile"
    if "/composeResources/" in path:
        return "resources (strings, fonts, images)"
    return "app shell (composeApp, other packages)"


def scan(root="."):
    listed = subprocess.run(["git", "-C", root, "ls-files", *ROOTS], capture_output=True, text=True, check=True)
    files = collections.Counter()
    hits = collections.defaultdict(collections.Counter)
    for path in listed.stdout.split():
        if not SOURCE.search(path) or TEST.search(path):
            continue
        area = area_of(path)
        files[area] += 1
        text = (Path(root) / path).read_text(errors="ignore")
        for name, (pattern, _, _) in CATEGORIES.items():
            count = len(re.findall(pattern, text))
            if count:
                hits[area][name] += count
    return files, hits


def table(files, hits):
    rows = ["# Build 15 — initial pass over every source area (S19-03)", "",
            "Generated by `.github/plus/initial-pass.py`; `--check` in the script tests keeps it current.",
            "Every non-test source file is in one area below. Each pattern category was read hit by hit;",
            "the verdict applies wherever the category occurs. This is the initial pass the spec asks for, not a",
            "deep audit: deep reviews are the findings in `audit.md` (Plus areas, player, downloads, updater).", "",
            "## Categories and verdicts", "", "| Category | Verdict after reading the hits | Findings |", "|---|---|---|"]
    for name, (_, verdict, findings) in CATEGORIES.items():
        rows.append(f"| {name} | {verdict} | {', '.join(findings) or '—'} |")
    rows += ["", "## Areas", "", "| Area | Files | Hits | Result |", "|---|---|---|---|"]
    for area in sorted(files):
        if area in EXCLUDED:
            rows.append(f"| {area} | {files[area]} | — | EXCLUDED: {EXCLUDED[area]} |")
            continue
        found = hits.get(area, {})
        counts = ", ".join(f"{k} {v}" for k, v in sorted(found.items())) or "—"
        ids = sorted({i for k in found for i in CATEGORIES[k][2]})
        rows.append(f"| {area} | {files[area]} | {counts} | {', '.join(ids) if ids else 'reviewed, none'} |")
    return "\n".join(rows) + "\n"


def main(argv):
    text = table(*scan())
    if "--write" in argv:
        Path(OUT).write_text(text)
        return 0
    if "--check" in argv:
        current = Path(OUT).read_text() if Path(OUT).exists() else ""
        if current != text:
            print(f"{OUT} is out of date: run .github/plus/initial-pass.py --write")
            return 1
        return 0
    sys.stdout.write(text)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
